-- External locations (SQL alternative to the UI)
CREATE EXTERNAL LOCATION IF NOT EXISTS ext_data
  URL 'abfss://data@<storage-account>.dfs.core.windows.net/'
  WITH (STORAGE CREDENTIAL najd_banking_cred);

CREATE EXTERNAL LOCATION IF NOT EXISTS ext_catalog_location
  URL 'abfss://catalog-location@<storage-account>.dfs.core.windows.net/'
  WITH (STORAGE CREDENTIAL najd_banking_cred);

-- Catalog with its own managed storage
CREATE CATALOG IF NOT EXISTS banking
  MANAGED LOCATION 'abfss://catalog-location@<storage-account>.dfs.core.windows.net/'
  COMMENT 'Najd National Bank - re-delinquency analytics';

USE CATALOG banking;

CREATE SCHEMA IF NOT EXISTS bronze COMMENT 'Raw feeds from core banking extracts';
CREATE SCHEMA IF NOT EXISTS silver COMMENT 'Cleaned, masked, conformed dims and fact';
CREATE SCHEMA IF NOT EXISTS gold   COMMENT 'Business KPIs';

import pandas as pd
from pyspark.sql.functions import pandas_udf
from hijridate import Gregorian

@pandas_udf("string")
def to_hijri(d: pd.Series) -> pd.Series:
    return d.apply(lambda x: None if pd.isna(x)
                   else Gregorian(x.year, x.month, x.day).to_hijri().isoformat())

GRANT USE CATALOG ON CATALOG banking TO `collections-analysts`;
GRANT USE SCHEMA, SELECT ON SCHEMA banking.silver TO `collections-analysts`;
GRANT USE SCHEMA, SELECT ON SCHEMA banking.gold   TO `collections-analysts`;
